def seed_admission_configuration_data(apps, schema_editor):
    AdmissionConfiguration = apps.get_model("mainapp", "AdmissionConfiguration")
    AdmissionResult = apps.get_model("mainapp", "AdmissionResult")
    Department = apps.get_model("mainapp", "Department")
    DepartmentThreshold = apps.get_model("mainapp", "DepartmentThreshold")

    for threshold in DepartmentThreshold.objects.select_related("exam", "department"):
        config, _ = AdmissionConfiguration.objects.update_or_create(
            department=threshold.department,
            semester=threshold.exam.semester,
            defaults={
                "exam": threshold.exam,
                "threshold": threshold.min_threshold_mark,
            },
        )

        AdmissionResult.objects.filter(
            exam=threshold.exam,
            department=threshold.department,
        ).update(configuration=config)

    for result in AdmissionResult.objects.select_related("exam", "student", "department"):
        department = result.department
        if department is None:
            department = Department.objects.filter(
                department_shortname__iexact=result.exam.department
            ).first() or Department.objects.filter(
                department_name__iexact=result.exam.department
            ).first()

        configuration = None
        if department:
            configuration, _ = AdmissionConfiguration.objects.get_or_create(
                department=department,
                semester=result.exam.semester,
                defaults={
                    "exam": result.exam,
                    "threshold": float(result.threshold_applied or 0.0),
                },
            )

        weighted_total = float(result.total_marks or result.mcq_marks + result.viva_marks)
        attended_exam = weighted_total > 0
        if not attended_exam:
            result_status = "ABSENT"
        elif result.is_selected:
            result_status = "WAITING"
        else:
            result_status = "REJECTED"

        result.configuration = configuration
        result.department = department
        result.written_viva_total = float(result.total_marks or 0.0)
        result.weighted_total_marks = weighted_total
        result.attended_exam = attended_exam
        result.result_status = result_status
        result.ssc_score = float(getattr(result.student, "ssc", 0.0) or 0.0)
        result.academic_score = float(
            getattr(result.student, "diploma", 0.0)
            or getattr(result.student, "hsc", 0.0)
            or 0.0
        )
        result.academic_source = (
            "DIPLOMA"
            if float(getattr(result.student, "diploma", 0.0) or 0.0) > 0
            else "HSC"
            if float(getattr(result.student, "hsc", 0.0) or 0.0) > 0
            else "NONE"
        )
        result.save(
            update_fields=[
                "configuration",
                "department",
                "written_viva_total",
                "weighted_total_marks",
                "attended_exam",
                "result_status",
                "ssc_score",
                "academic_score",
                "academic_source",
            ]
        )


def noop_reverse(apps, schema_editor):
    pass


